steps.script:
# M and Advance come from RulesEngine, fed the phase's live active move.
var mc = tree.root.get_node("Main").movement_controller
var b: Dictionary = mc.drag_budget_for_unit("U_BLADE_CHAMPION_A")
var from_rules: Dictionary = RulesEngine.movement_drag_budget(PhaseManager.current_phase_instance.get_active_move_data("U_BLADE_CHAMPION_A"))
return b == from_rules and b.move == 6.0 and b.advance == 6.0

# Precondition: the lane costs no terrain, so the bands fall at exactly 6" and 12".
var mc = tree.root.get_node("Main").movement_controller
return mc._get_terrain_penalty_for_move(Vector2(120, 100), Vector2(120, 660))

# The ghost is held at the 6" cap while the ruler runs on to the 9" cursor.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var ghost_in = Measurement.px_to_inches((m.get_node("BoardRoot/MovementGhostVisual").position - mc.drag_start_pos).length())
return abs(ghost_in - 6.0) <= 0.05 and mc.drag_cursor_pos.distance_to(Vector2(120, 460)) < 0.5

# ESC cancelled the drag cleanly: nothing held, no ruler / label / ghost,
# nothing staged — and the pause menu did NOT open underneath.
var m = tree.root.get_node("Main")
var mc = m.movement_controller
var label = mc.drag_ruler_visual.get_node("DragRulerLabel")
var staged = PhaseManager.current_phase_instance.get_active_move_data("U_BLADE_CHAMPION_A").get("staged_moves", [])
var menu_closed = m._settings_menu == null or not is_instance_valid(m._settings_menu)
return not mc.dragging_model and mc.current_drag_segments.is_empty() and not mc.is_drag_ruler_showing() and not label.visible and m.get_node("BoardRoot/MovementGhostVisual").get_child_count() == 0 and staged.is_empty() and menu_closed

# ENTER committed the path leg by leg: the phase charged the path walked
# (3" + 3" = 6.0", not the 4.24" crow-flies), staged the model at the cursor,
# and the Movement phase is still running (ENTER did not end it).
var m = tree.root.get_node("Main")
var md = PhaseManager.current_phase_instance.get_active_move_data("U_BLADE_CHAMPION_A")
var d = float(md.model_distances.get("U_BLADE_CHAMPION_A:m1", -1.0))
var sm: Array = md.staged_moves
var menu_closed = m._settings_menu == null or not is_instance_valid(m._settings_menu)
return not m.movement_controller.dragging_model and abs(d - 6.0) <= 0.05 and sm.size() == 1 and sm[0].dest.distance_to(Vector2(240, 220)) < 0.5 and GameState.get_current_phase() == 7 and menu_closed
